function normalize(pathname: string) {
  const base = String(pathname || '').split('?')[0]?.replace(/\/$/, '') || '/angelcare-360-command-center'
  return base || '/angelcare-360-command-center'
}
function routePattern(route: string) {
  const escaped = route.replace(/[.*+?^${}()|[\]\\]/g, '\\$&').replace(/\\\[[^/]+\\\]/g, '[^/]+')
  return new RegExp(`^${escaped}/?$`)
}
export function resolveSanilaReleaseRouteAuthority(pathname: string): SanilaReleaseRouteAuthority | null {
  const normalized = normalize(pathname)
  const exact = SANILA_RELEASE_ROUTE_CONSTITUTION.find((item) => item.route === normalized)
  if (exact) return exact
  return SANILA_RELEASE_ROUTE_CONSTITUTION.find((item) => item.route.includes('[') && routePattern(item.route).test(normalized)) || null
}
